from lib import *
S = SS('h1')
steps = [
    step("在客户端和服务端之间放一个 TCP 抓包代理(我自己写的,用 golang.org/x/net/http2 的 Framer 解析帧),调用一次 Unary(Req{msg:\"hello\", n:7}),看到的帧按顺序是:客户端发 24 字节的连接前言(PRI * HTTP/2.0…)和一个空的 SETTINGS;服务端回 SETTINGS(MAX_FRAME_SIZE=16384)并确认对方的;客户端在流 1 上发 HEADERS(82 字节)和带 END_STREAM 的 DATA(14 字节);服务端回 WINDOW_UPDATE、PING,然后在流 1 上回 HEADERS(14 字节,:status 200)、DATA(19 字节)和带 END_STREAM 的 HEADERS(24 字节,grpc-status: 0);两边还各发一次 PING 和 WINDOW_UPDATE。含建立连接的整个调用用了 2.3 ms。", t=tl(S(1)), done=lidx(S(1), 'C→S HEADERS       流 1'), mark=lidx(S(1), 'C→S PREFACE'), b=bars([['请求 HEADERS 负载 字节', 82, '82'], ['请求 DATA 负载 字节', 14, '14'], ['响应 DATA 负载 字节', 19, '19'], ['响应 trailers 负载 字节', 24, '24']], 90, done=[1, 2], mark=[0]), kv=KV([['一次调用', '流 1:请求 HEADERS + DATA,响应 HEADERS + DATA + trailers'], ['连接前言', '24 字节 PRI * HTTP/2.0…,再加双方 SETTINGS'], ['整个调用', '2.3 ms(含建立连接)']], ['一次调用'])),
    step("请求的 HEADERS 帧里(HPACK 解码后)有 8 个头::method: POST、:scheme: http、:path: /demo.Demo/Unary(/包名.服务名/方法名)、:authority: 127.0.0.1:9801、content-type: application/grpc、user-agent: grpc-go/1.84.0、te: trailers、grpc-timeout: 4998325u(截止时间,单位是微秒的数字加一个字母 u;约 5 秒)。方法一律是 POST,路径就是 RPC 的全名,没有 REST 式的资源路径。这个 HEADERS 帧的负载是 82 字节。", t=tl(S(2)), done=lidx(S(2), '  :path'), mark=lidx(S(2), '  grpc-timeout'), b=bars([['请求头个数', 8, '8'], ['HEADERS 帧负载 字节', 82, '82']], 90, done=[0, 1]), kv=KV([[':path', '/demo.Demo/Unary(包名.服务名/方法名)'], ['content-type', 'application/grpc'], ['grpc-timeout', '4998325u(约 5 秒,单位微秒)']], [':path'])),
    step("请求消息放在 DATA 帧里:负载 14 字节 00 00000009 0a0568656c6c6f 1007。第 1 个字节是压缩标志(0 表示没压缩),第 2–5 个字节是消息长度(大端,9),后面 9 个字节是 protobuf 载荷 0a0568656c6c6f1007(字段 1 的字符串 hello,字段 2 的 varint 7)。我自己对 Req{msg:hello,n:7} 调 proto.Marshal 得到的字节与它完全相同。所以 gRPC 的一条消息 = 5 字节前缀 + 普通的 protobuf。", t=tl(S(3)), done=lidx(S(3), '载荷 0a0568656c6c6f1007'), mark=lidx(S(3), 'DATA 帧负载共 14 字节'), b=bars([['DATA 帧负载', 14, '14'], ['其中前缀', 5, '5'], ['其中 protobuf', 9, '9']], 15, done=[2], mark=[1]), kv=KV([['第 1 字节', '压缩标志(0 = 没压缩)'], ['第 2–5 字节', '消息长度,大端,这里是 9'], ['后面', 'protobuf 载荷,与 proto.Marshal 的结果相同']], ['第 2–5 字节'])),
    step("响应分三段:先是 HEADERS(:status: 200; content-type: application/grpc,14 字节负载),然后是 DATA(19 字节,同样的 5 字节前缀 000000000e 加 14 字节 protobuf),最后是带 END_STREAM 的 HEADERS(grpc-status: 0; grpc-message: ,24 字节负载)。最后这段在 HTTP 里叫 trailers。调用是否成功不是看 HTTP 的 :status(那里永远是 200),而是看最后的 grpc-status:0 表示成功。", t=tl(S(4)), done=lidx(S(4), '流 1 HEADERS 标志 END_STREAM|END_HEADERS'), mark=lidx(S(4), '流 1 HEADERS 标志 END_HEADERS'), b=bars([['响应 HEADERS 负载', 14, '14'], ['响应 DATA 负载', 19, '19'], ['响应 trailers 负载', 24, '24']], 25, done=[2]), kv=KV([['HEADERS', ':status: 200,content-type: application/grpc'], ['DATA', '5 字节前缀 + protobuf'], ['trailers', 'grpc-status: 0,带 END_STREAM']], ['trailers'])),
    step("一次调用在网线上的字节数(代理统计的 TCP 字节数,含建立连接的 preface 和 SETTINGS):客户端到服务端 203 字节,服务端到客户端 155 字节;而请求消息本身 protobuf 只有 9 字节,响应 14 字节。首次调用的绝大部分字节是连接建立和请求头(82 字节的 HEADERS),不是业务数据。", t=tl(S(5)), done=lidx(S(5), '客户端→服务端 203'), b=bars([['客户端→服务端 字节', 203, '203'], ['服务端→客户端 字节', 155, '155'], ['请求 protobuf', 9, '9'], ['响应 protobuf', 14, '14']], 210, done=[0, 1]), kv=KV([['首次调用 C→S', '203 字节'], ['首次调用 S→C', '155 字节'], ['业务数据', '请求 9 字节,响应 14 字节']], ['首次调用 C→S'])),
    step("在同一条连接上第二次调用:没有新的 SETTINGS 和连接前言,请求用流 3;请求的 HEADERS 帧负载从第一次的 82 字节降到 15 字节,响应的 HEADERS 从 14 字节降到 2 字节、trailers 从 24 降到 2——因为 HPACK 把前面发过的头存进动态表,以后只发索引。这一次调用的 TCP 字节数:客户端到服务端 94,服务端到客户端 97;用时 0.4 ms。连接是长期复用的,首次的建立成本只付一次。", t=tl(S(6)), done=lidx(S(6), '请求 HEADERS 帧负载:第一次'), mark=lidx(S(6), '第二次调用用时'), b=bars([['请求 HEADERS:第一次', 82, '82'], ['请求 HEADERS:第二次', 15, '15'], ['C→S 字节:第一次', 203, '203'], ['C→S 字节:第二次', 94, '94']], 210, mark=[0, 2], done=[1, 3]), kv=KV([['请求 HEADERS', '82 → 15 字节(HPACK 动态表)'], ['响应 HEADERS / trailers', '14 → 2、24 → 2 字节'], ['第二次调用', 'C→S 94 字节,S→C 97 字节,0.4 ms']], ['请求 HEADERS'])),
]
A = mkarth('h1', 1, 'gRPC,HTTP/2,帧,protobuf,抓包,HPACK,Go,真实验证,动画演示',
    '用自己写的 TCP 抓包代理看一次 gRPC Unary 调用的 HTTP/2 帧:请求是 HEADERS 加 DATA,响应是 HEADERS、DATA 和带 grpc-status 的 trailers;消息是 5 字节前缀加 protobuf;首次调用请求头 82 字节,第二次因为 HPACK 只有 15 字节。',
    'gRPC 常被说成“基于 HTTP/2 的 RPC”,但一次调用在网线上到底是什么样?这篇在客户端和服务端之间放一个抓包代理,把一个最简单的 Unary 调用的每一帧、每个头、每个字节都拆开看。',
    [('5 字节', 'gRPC 每条消息前面的前缀:1 字节压缩标志加 4 字节长度'), ('82 对 15 字节', '同一条连接上请求 HEADERS 帧的负载:第一次调用与第二次调用(HPACK 动态表)'), ('grpc-status: 0', '调用是否成功放在最后的 trailers 里,HTTP 的 :status 永远是 200')],
    [('一次调用的帧', '<p>连接上先交换 24 字节的前言和 SETTINGS。每个调用占一条 HTTP/2 流(流 1、3、5……),请求是 HEADERS 加带 END_STREAM 的 DATA,响应是 HEADERS、DATA 和带 END_STREAM 的 HEADERS(trailers)。</p>'),
     ('请求头', '<p>方法永远是 POST,路径是 /包名.服务名/方法名,content-type 是 application/grpc,te: trailers 表示客户端能接收 trailers,grpc-timeout 带着截止时间(单位微秒)。这就是 gRPC 对 HTTP/2 的全部约定。</p>'),
     ('消息格式', '<p>一条消息 = 1 字节压缩标志 + 4 字节大端长度 + protobuf 载荷。载荷与直接 proto.Marshal 的结果相同,所以任何能看懂 HTTP/2 和 protobuf 的工具都能解它(见 protobuf 那一篇的字节拆解)。</p>'),
     ('状态在 trailers 里', '<p>响应的 HTTP 状态永远是 200,调用成败看最后 trailers 里的 grpc-status 和 grpc-message。也因此只能到流结束才知道结果(下一篇再展开)。</p>'),
     ('首次调用的成本', '<p>首次调用客户端发 203 字节、服务端发 155 字节,而业务数据只有 9 和 14 字节;大头是连接建立和 82 字节的请求头。</p>'),
     ('连接复用与 HPACK', '<p>第二次调用不需要重新握手,请求头靠 HPACK 动态表从 82 字节降到 15 字节,响应头从 14 降到 2,trailers 从 24 降到 2。这是 gRPC 小消息仍然高效的原因之一。</p>')],
    steps,
    [ENV_H + '。抓包代理是我写的 TCP 转发加 http2.Framer 解析,看到的是明文 HTTP/2(没有 TLS);观察中还有 PING 和 WINDOW_UPDATE 帧,它们是 grpc-go 的 BDP 流控估计(第 10 篇)产生的,这里只记录了现象;所有字节数是确定性的,耗时是单次测量',
     '没有验证:grpc-go 以外实现(Java、C++)的帧序列;TLS 下的帧长度(多了 TLS 记录的开销);其它版本 grpc-go 的头(比如 grpc-accept-encoding 是否出现);HPACK 动态表大小的上限与淘汰;HTTP/2 之外的传输(gRPC over HTTP/3)'],
    '一次调用的字节')
